  backing: number | null;
  net: number | null;
  rank: number | null;
  percentile: number | null;
  onset: string | null;
export interface NewPerson {
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  delta: number | null;
  epsilon: number | null;
  grade: Grade | null;
